entries[78345] = { ["name"] = "Muster: Grüne Drachenschuppengamaschen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung von grünen Drachenschuppengamaschen.\nBenötigt Klassische Lederverarbeitung (270)\nVerkaufspreis:\nGrüne Drachenschuppengamaschen\nWird beim Anlegen gebunden\nBeine Kette\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+5 Ausdauer\n+2 Naturwiderstand\nHaltbarkeit 100 / 100\n\nGrüner Drachenschuppenpanzer (0/3)\nGrüne Drachenschuppenbrustplatte\nGrüne Drachenschuppengamaschen\nGrüne Drachenschuppenstulpen\nVerkaufspreis:\nBenötigt Unverwüstliches Leder (20), Grüne Drachenschuppe (25), Runenfaden\nOptionale Reagenzien: [] (#50)" }
entries[78346] = { ["name"] = "Muster: Grüne Drachenschuppenbrustplatte", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung einer grünen Drachenschuppenbrustplatte.\nBenötigt Klassische Lederverarbeitung (260)\nVerkaufspreis:\nGrüne Drachenschuppenbrustplatte\nWird beim Anlegen gebunden\nBrust Kette\n9 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+5 Ausdauer\n+2 Naturwiderstand\nHaltbarkeit 140 / 140\n\nGrüner Drachenschuppenpanzer (0/3)\nGrüne Drachenschuppenbrustplatte\nGrüne Drachenschuppengamaschen\nGrüne Drachenschuppenstulpen\nVerkaufspreis:\nBenötigt Unverwüstliches Leder (20), Grüne Drachenschuppe (25), Runenfaden (2)\nOptionale Reagenzien: [] (#50)" }
entries[78348] = { ["name"] = "Formel: Waffe - Scharfrichter", ["text"] = "Benutzen: Lehrt Euch24 wie man die Verzauberung 'Scharfrichter' durchführt.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass der kritische Trefferwert gelegentlich um 24 erhöht wird. Dieser Effekt ist nicht stapelbar. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Verzauberkunst der Scherbenwelt (75)\nVerkaufspreis:" }
