entries[78471] = { ["name"] = "Vishanka, Rachen der Erde", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nDistanz Bogen\n7 - 11 Schaden Geschwindigkeit 3.00\n(3.0 Schaden pro Sekunde)\n+4 Beweglichkeit\n+6 Ausdauer\nHaltbarkeit 120 / 120\nAnlegen: Distanzangriffe gewähren eine Chance, 2 Sek. lang 6 Feuerschaden zu verursachen. (Procchance: 15%, 17s Abklingzeit)\nVerkaufspreis:" }
entries[78472] = { ["name"] = "No'Kaled, die Elemente des Todes", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nEinhändig Axt\n3 - 8 Schaden Geschwindigkeit 2.60\n(2.1 Schaden pro Sekunde)\n+2 Beweglichkeit\n+3 Ausdauer\nHaltbarkeit 110 / 110\nAnlegen: Eure Nahkampfangriffe gewähren eine Chance, Euer Ziel zusätzlich mit 7 Feuer-, Frost- oder Schattenschaden zu überziehen. (Procchance: 7%)\nVerkaufspreis:" }
entries[78473] = { ["name"] = "Kiril, Zorn der Bestien", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nZweihändig Stangenwaffe\n7 - 14 Schaden Geschwindigkeit 3.60\n(2.9 Schaden pro Sekunde)\n+4 Beweglichkeit\n+6 Ausdauer\n+ 8 Vielseitigkeit\nHaltbarkeit 120 / 120\nAnlegen: Eure Nahkampf- und Distanzangriffe gewähren eine Chance, den Effekt 'Furor der Bestie' auszulösen, der alle 1 Sek. sowohl Eure Beweglichkeit um 1 als auch Eure Größe um 10% erhöht. Dieser Effekt ist bis zu 10-mal stapelbar und hält 20 Sek. lang an. (Procchance: 15%, 55s Abklingzeit)\nVerkaufspreis:" }
entries[78474] = { ["name"] = "Klinge des Beseitigers", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nEinhändig Dolch\n3 - 5 Schaden Geschwindigkeit 1.80\n(2.2 Schaden pro Sekunde)\n+2 Beweglichkeit\n+3 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 80 / 80\nVerkaufspreis:" }
