entries[78911] = { ["name"] = "Unversehrte Huscherdrüsen", ["text"] = "Questgegenstand\n\"Ein widerlicher Anblick, und doch hat ihr Aroma eine heilende Wirkung.\"" }
entries[78914] = { ["name"] = "Mit Tigerblut gefüllte Phiole", ["text"] = "Questgegenstand\n\"Eine ganze Phiole voll Siegesgefühl.\"" }
entries[78916] = { ["name"] = "Seele der Aspekte", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren Seele der Aspekte beschwören oder wieder freigeben.\n80 ( 80)" }
entries[78917] = { ["name"] = "Dojanibefehle", ["text"] = "Questgegenstand\n\"Eine Reihe grober Zeichnungen stellt bestimmte Moguartefakte dar, die bei den Ruinen von Dojan gefunden werden können.\"\n<Zum Lesen rechtsklicken>" }
entries[78918] = { ["name"] = "Kaiserliche Lotusblätter", ["text"] = "Questgegenstand\n\"Von diesen hässlichen Blättern strömt ein beißender Geruch aus.\"" }
entries[78919] = { ["name"] = "Experiment 12-B", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört das reitbare Experiment 12-B oder gibt es wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Einige sind davon überzeugt, dass Experiment 12-B das Resultat einer geheimen SI-7-Initiative war. Andere meinen, es war das Ergebnis von embryonaler Modifikation durch Goblinwissenschaftler. Natürlich ist dies egal, denn eins ist klar: Wenn man die Stärke, Geschwindigkeit und Beweglichkeit betrachtet, war Experiment 12-B offensichtlich ein Erfolg!\"\nBeute von:\nGeringere Truhe der Aspekte\nOrt:\nDrachenseele" }
entries[78924] = { ["name"] = "Herz der Aspekte", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört das Herz der Aspekte oder gibt es wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ihr seid Azeroths wahre Wächter, und die Zukunft dieser Welt liegt in Euren Händen, denn das Zeitalter der Sterblichen hat begonnen. - Alexstrasza\"\nWoW-Shop" }
entries[78928] = { ["name"] = "Flamme von Zhus Wacht", ["text"] = "Questgegenstand\nBenutzen: Entzündet ein Gedenkfeuer in der Provinz Zhu. (3 Sek. Abklingzeit)" }
