entries[78934] = { ["name"] = "Das Wasser der Jugend", ["text"] = "Questgegenstand\n\"Allein, wenn Ihr die Phiole nur berührt, fühlt Ihr Euch bereits jünger und lebendiger.\"" }
entries[78941] = { ["name"] = "Riesiger Pantherreißzahn", ["text"] = "Questgegenstand\n\"Ein riesiger, scharfer Reißzahn. Hoffentlich unterscheidet sich Ken-Kens neuer Plan deutlich von seinem letzten.\"" }
