entries[78947] = { ["name"] = "Seidenes Seil", ["text"] = "Questgegenstand\nBenutzen: Schlingt ein seidenes Seil über den Kopf eines Windwärtsjungtiers.\n\"Aus den feinsten Seiden gedreht, um zarten Hälsen keine Blessuren zuzufügen.\"" }
entries[78958] = { ["name"] = "Geplünderte Jinyubeute", ["text"] = "Questgegenstand\n\"Eine Sammlung von Vasen, Nippes und anderen gemischten Waren, die den einfachen Flussleuten viel bedeuten.\"" }
