entries[79327] = { ["name"] = "Reliquie von Xuen", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Dunkelmond-Karte der Nebel (1)\nSchmuck\n+4 Stärke\nAnlegen: Eure Nahkampfangriffe gewähren eine Chance, Euch 'Segen der Erhabenen' zu gewähren und Eure Stärke 15 Sek. lang um 12 zu erhöhen. (20% Chance, 55 Sek. Abklingzeit) (Procchance: 20%, 55s Abklingzeit)\nVerkaufspreis:" }
entries[79328] = { ["name"] = "Reliquie von Xuen", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Dunkelmond-Karte der Nebel (1)\nSchmuck\n+4 Beweglichkeit\nAnlegen: Eure kritischen Distanz- und Nahkampftreffer haben eine Chance, Euch 'Segen der Erhabenen' zu gewähren und Eure Beweglichkeit 15 Sek. lang um 12 zu erhöhen. (Procchance: 20%, 55s Abklingzeit)\nVerkaufspreis:" }
entries[79329] = { ["name"] = "Relikt von Niuzao", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Dunkelmond-Karte der Nebel (1)\nSchmuck\n+6 Ausdauer\nBenutzen: Gewährt 10 Sek. lang 5 Rüstung. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[79330] = { ["name"] = "Relikt von Chi-Ji", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Dunkelmond-Karte der Nebel (1)\nSchmuck\n+5 Intelligenz\nAnlegen: Eure Heilzauber haben eine Chance, Euch 'Segen der Erhabenen' zu gewähren und Eure Vielseitigkeit 20 Sek. lang um 18 zu erhöhen. (20% Chance, 55 Sek. Abklingzeit) (Procchance: 20%, 55s Abklingzeit)\nVerkaufspreis:" }
entries[79331] = { ["name"] = "Reliquie von Yu'lon", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Dunkelmond-Karte der Nebel (1)\nSchmuck\n+4 Intelligenz\nAnlegen: Wenn Ihr Zauberschaden verursacht, besteht eine Chance, dass Ihr den Effekt 'Segen der Erhabenen' erhaltet, der Eure Intelligenz 15 Sek. lang um 12 erhöht. (Procchance: 20%, 50s Abklingzeit)\nVerkaufspreis:" }
