entries[79344] = { ["name"] = "Pomerntefeuerwerk", ["text"] = "Questgegenstand\nBenutzen: Schießt Feuerwerk ab, um in der Nähe befindliche Pomfrüchte von ihren Zweigen zu schütteln. (3 Sek. Abklingzeit)" }
