entries[79917] = { ["name"] = "Verschlissenes Kassenbuch eines Architekten", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verpackt das restaurierte Artefakt vorsichtig.\n\"Die Einzelheiten dieses Artefakts wurden bereits in Eurem Archäologiebuch unter 'Restaurierte Artefakte' protokolliert.\"\nVerkaufspreis:" }
entries[79929] = { ["name"] = "Qu-Mo-Maske", ["text"] = "Questgegenstand\nEinzigartig\n\"Sieht gruselig aus.\"" }
entries[79932] = { ["name"] = "Qu-Mo-Maske", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Setzt die Qu-Mo-Maske einem besudelten Jinyu auf, um die Manifestation des Zorns aus ihm zu exorzieren.\n\"Sieht gruselig aus.\"" }
entries[79952] = { ["name"] = "Geruchsintensive Waldgeisternadeln", ["text"] = "Questgegenstand\n\"Diese Nadeln duften stark nach frischer Kiefer.\"" }
entries[80008] = { ["name"] = "Dunkelmond-Kaninchen", ["text"] = "Wird beim Anlegen gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euer Dunkelmond-Kaninchen beschwören oder wieder freigeben.\n80 ( 80)" }
entries[80013] = { ["name"] = "Schattenmeisterin Kiryns Bericht", ["text"] = "Questgegenstand\nEinzigartig\n\"Alles scheint in Ordnung zu sein. Der Vorschlag, Giftsprengsätze an Ho-zen anzuheften kommt Euch allerdings merkwürdig vor...\"" }
entries[80014] = { ["name"] = "Nieti Kuppelplopps Bericht", ["text"] = "Questgegenstand\nEinzigartig\n\"Direkt, sachlich und überraschend optimistisch.\"" }
entries[80015] = { ["name"] = "Shokias Bericht", ["text"] = "Questgegenstand\nEinzigartig\n\"Shokias Sprache, insbesondere ihre Beschreibungen der Ho-zen, lässt nur wenig zu wünschen übrig.\"" }
entries[80040] = { ["name"] = "Endloser Heiltrank des Meisters", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt 2200 Gesundheit wieder her. (5 Min Abklingzeit)\nBenötigt Alchemie von Pandaria\n(25)\n\"Wird bei der Nutzung nicht verbraucht.\"" }
entries[80061] = { ["name"] = "Rikos Bericht", ["text"] = "Questgegenstand\nEinzigartig\n\"Obwohl der Bericht jegliche für Euch erkennbaren Wörter vermissen lässt, könnt Ihr eine Zeichnung mit mehreren Glitschis erkennen. Jetzt müsst Ihr nur noch die richtigen Schlüsse ziehen.\"" }
entries[80071] = { ["name"] = "Erbstück der Familie Cho", ["text"] = "Questgegenstand\n\"Von Generation zu Generation unzähliger Urahnen der Chos weitergereicht.\"" }
entries[80074] = { ["name"] = "Himmlische Jade", ["text"] = "Questgegenstand\nBenutzen: Kann benutzt werden, um Sha-Rückstände zu schwächen. (5 Sek. Abklingzeit)\n\"Die Jade gibt ein sanftes Glühen ab.\"" }
entries[80116] = { ["name"] = "Angenagte Karotte", ["text"] = "Questgegenstand\n\"Übersät mit den Abdrücken scharfer Zähne, die jedoch zu klein sind, um von einem Shed-Ling zu stammen.\"" }
entries[80122] = { ["name"] = "Spinnenwurz", ["text"] = "Questgegenstand\n\"Die dornige Wurzel enthält eine säuerliche Flüssigkeit.\"" }
entries[80127] = { ["name"] = "Dimmlichttrüffelsporen", ["text"] = "Questgegenstand\nBenutzen: Pflanzt einige Dimmlichttrüffelsporen in den Boden. Dimmlichttrüffeln wachsen nur im Hochland von Kunzen oder auf der Himmelsweite." }
entries[80133] = { ["name"] = "Konserviertes Gemüse", ["text"] = "Questgegenstand\n\"Entweder hat ihnen der Geschmack nicht zugesagt, oder sie konnten das Gefäß nicht öffnen.\"" }
entries[80134] = { ["name"] = "Roher Chrysoberyll", ["text"] = "Questgegenstand\n\"Der Edelstein ändert langsam seine Farbe, während er die Wärme Eurer Hand absorbiert.\"" }
entries[80136] = { ["name"] = "Gewachstes Brett", ["text"] = "Questgegenstand\n\"Ein Stück stabiles Bambusholz.\"\nVerkaufspreis:" }
entries[80137] = { ["name"] = "Geplünderter Ring", ["text"] = "Questgegenstand\n\"Passt perfekt auf den nicht ganz so zarten Finger eines Pandaren.\"" }
entries[80138] = { ["name"] = "Gestohlener Reif", ["text"] = "Questgegenstand\n\"Jemand hat viel Geld dafür ausgegeben.\"" }
entries[80139] = { ["name"] = "Stibitztes Armband", ["text"] = "Questgegenstand\n\"Es besteht größtenteils aus Silber, jedoch mit Gold- und Jadebesatz.\"" }
entries[80140] = { ["name"] = "Blutblüte", ["text"] = "Questgegenstand\n\"Die dunkle Färbung dieser Pflanze beruht auf ihrer Eigenschaft, Mineralien aus der Erde zu saugen.\"\nVerkaufspreis:" }
entries[80141] = { ["name"] = "Höhlenlilie", ["text"] = "Questgegenstand\n\"Diese wunderschöne weiße Pflanze gedeiht in dunklen, feuchten Höhlen.\"\nVerkaufspreis:" }
entries[80142] = { ["name"] = "Geisterkappe", ["text"] = "Questgegenstand\n\"Ein schauriges Glühen geht von diesem seltenen Pilz aus.\"\nVerkaufspreis:" }
entries[80143] = { ["name"] = "Veilchenflechte", ["text"] = "Questgegenstand\n\"Ein seltenes Moos, das in großen Höhen wächst.\"\nVerkaufspreis:" }
entries[80144] = { ["name"] = "Köstliches T-Bone-Steak", ["text"] = "Questgegenstand\n\"Ein riesiges, saftiges Stück fettes Fleisch.\"\nVerkaufspreis:" }
entries[80176] = { ["name"] = "Getriebeteile mit Wasserschaden", ["text"] = "Questgegenstand\n\"Leicht nass - Ihr hofft, es ist Meerwasser und kein Ho-zensabber.\"" }
entries[80177] = { ["name"] = "Rostiger Klemmbolzen", ["text"] = "Questgegenstand\n\"Rostbedeckt und fast unbrauchbar.\"" }
entries[80184] = { ["name"] = "Rosa Melone", ["text"] = "Questgegenstand\n\"Diese saftige, süße Melone wächst nur im Kernland.\"\nVerkaufspreis:" }
entries[80212] = { ["name"] = "Die Flamme des Meisters", ["text"] = "Questgegenstand\nEinzigartig\nIhr haltet die Flamme des Meisters in Euren Händen." }
entries[80213] = { ["name"] = "Gewürzmeister Jin Jaos Bezahlung", ["text"] = "Questgegenstand\n\"Münzen klimpern darin.\"" }
entries[80214] = { ["name"] = "Händler Jambeezis Bezahlung", ["text"] = "Questgegenstand\n\"Riecht nach Yakhaar.\"" }
entries[80215] = { ["name"] = "Gastwirtin Lei Lans Bezahlung", ["text"] = "Questgegenstand\n\"Voller sorgfältig gefalteter Geldscheine.\"" }
entries[80216] = { ["name"] = "Lolo Lios Bezahlung", ["text"] = "Questgegenstand\n\"Vollgestopft mit zerknitterten Geldscheinen.\"" }
entries[80220] = { ["name"] = "Waldheilmittel", ["text"] = "Questgegenstand\nEinzigartig" }
entries[80222] = { ["name"] = "Kriegshelm des Donnerkönigs", ["text"] = "Questgegenstand\nEinzigartig\n\"Dieser uralte Helm ist auf Hochglanz poliert und zeigt nicht die Spur eines Kratzers.\"" }
entries[80223] = { ["name"] = "Zuchthenne vom alten Hügelpranke", ["text"] = "Questgegenstand\n\"Bei näherer Betrachtung... das ist eine echt gute Henne.\"" }
entries[80227] = { ["name"] = "Wurzelgemüse", ["text"] = "Questgegenstand\n\"Frisch vom Hof.\"" }
entries[80228] = { ["name"] = "Zahn eines gewaltigen Rohrkolbenbarschs", ["text"] = "Questgegenstand\n\"Er ist makellos und ideal für eine Halskette oder ein Armband geeignet.\"" }
entries[80229] = { ["name"] = "Blaue Süßwasserperle", ["text"] = "Questgegenstand\n\"Sie ist blau.\"" }
entries[80230] = { ["name"] = "Gusseiserner Topf", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Innenseite ist überzogen mit einer dicken Schicht Yakfett.\"" }
entries[80231] = { ["name"] = "Goldfeuerorchidee", ["text"] = "Questgegenstand\n\"Ihr müsst Euch sorgsam um sie kümmern – sie ist sehr empfindlich.\"" }
entries[80232] = { ["name"] = "Blutiges Ebenenfalkenbein", ["text"] = "Questgegenstand\n\"Der Ebenenfalke hatte zwar zwei Beine, aber dieses hier sah ein wenig wohlschmeckender aus.\"" }
entries[80233] = { ["name"] = "Gegrilltes Ebenenfalkenbein", ["text"] = "Questgegenstand\n\"Perfekt zubereitet!\"" }
entries[80234] = { ["name"] = "Yoons Apfel", ["text"] = "Questgegenstand\nEinzigartig (8)\n\"Er ist mittlerweile matschig und mehlig geworden, aber das sollte kein Problem sein.\"" }
entries[80235] = { ["name"] = "Yoons Kranichbeere", ["text"] = "Questgegenstand\nEinzigartig (50)\n\"Fast zu herb, um sie zu essen.\"" }
entries[80236] = { ["name"] = "Apfelbeerenfusel", ["text"] = "Questgegenstand\n\"Am besten aus einer Papiertüte getrunken.\"" }
entries[80240] = { ["name"] = "Seltsamer runder Stein", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\nBenötigt Alchemie von Pandaria\n(1)\n\"Eine raue Kugel, die aus dem heimischen Gestein Pandarias gehauen wurde.\"" }
entries[80241] = { ["name"] = "Moschusprankes Andenken", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"In diesen einfachen Armreif sind Symbole der Liebe und Zuneigung eingeritzt.\"" }
entries[80245] = { ["name"] = "Kun-Lai-Fleischbrocken", ["text"] = "Questgegenstand\n\"Es ist nicht wichtig, wo es herkommt. Was zählt, ist, dass es Fleisch ist - oder zumindest so aussieht.\"" }
entries[80260] = { ["name"] = "Dojaniaal", ["text"] = "Questgegenstand\n\"Den sollte man wohl lieber nicht zu lange in der Hand behalten.\"" }
entries[80262] = { ["name"] = "Geliebter Ring", ["text"] = "Questgegenstand\n\"Die Initialen J.H. sind auf der Innenseite des Ringes eingraviert.\"" }
entries[80277] = { ["name"] = "Fleisch eines gezackten Seeohrs", ["text"] = "Questgegenstand\n\"Leicht schleimig.\"" }
entries[80294] = { ["name"] = "Mogurelikt", ["text"] = "Questgegenstand\n\"Hiermit sollte man ein paar Münzen verdienen können.\"" }
entries[80295] = { ["name"] = "Päckchen mit Grünkohlsamen", ["text"] = "Questgegenstand\n\"Ein Papierumschlag, der rasselt, wenn er geschüttelt wird.\"" }
entries[80302] = { ["name"] = "Simp-L-WAX-Grünkohlsamen", ["text"] = "Questgegenstand\nBenutzen: Pflanzt Simp-L-WAX-Grünkohlsamen in einem Beet aus gepflügtem Erdreich.\n\"Diese speziell behandelten Samen sprießen und reifen schneller als gewöhnlich, erzeugen aber Gemüse von schlechterer Qualität. Nützlich, um neuen Bauern zu zeigen, wie der Hase läuft.\"" }
entries[80303] = { ["name"] = "Makelloses Kranichei", ["text"] = "Questgegenstand\nBenutzen: Erzeugt eine kleine Pfütze aus Eigelb, die Silbergrundeln in der Nähe anlockt." }
entries[80307] = { ["name"] = "Grummelbündel", ["text"] = "Questgegenstand\n\"Eine Ansammlung diverser Beutel, Säcke, Kisten und verschiedener Pakete, verschnürt mit Fäden und Seilen. Sie wiegt das Vielfache eines Grummels. Der Geruch von Räucherwerk und Yakmoschus durchdringt jeden Quadratzentimeter dieser Gegenstände.\"" }
entries[80308] = { ["name"] = "Feuerlotusräucherwerk", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Erweckt sogar in den feigsten Individuen Mut.\n\"Dieser hochwirksame Duft kann selbst den Zögerlichsten zu Heldentaten anspornen.\"" }
entries[80310] = { ["name"] = "Silbergrundel", ["text"] = "Questgegenstand\n\"Die Fische hier haben einen sehr seltsamen Geschmack, was Essen betrifft.\"" }
entries[80311] = { ["name"] = "Gefüllte Ölphiole", ["text"] = "Questgegenstand\n\"In dieser Phiole schwappt eine dunkle, stinkende Substanz.\"" }
entries[80312] = { ["name"] = "Leere Ölphiole", ["text"] = "Questgegenstand\nBenutzen: Füllt Phiole mit Yaungolöl.\n\"Diese leere Phiole eines Grummels riecht nach nassem Yak und Jasmin.\"" }
entries[80313] = { ["name"] = "Ling-Tings Lieblingstee", ["text"] = "Einzigartig (5)\nBenutzen: Könnte den Benutzer seltsame Dinge sehen lassen.\n\nKann nur in der Brauerei Sturmbräu verwendet werdet.\nVerkaufspreis:" }
entries[80314] = { ["name"] = "Simp-L-WAX-Grünkohl", ["text"] = "Questgegenstand\nEinzigartig (2)\n\"Eure erste Ernte! Auf dem Markt wird sie kaum etwas einbringen, aber der sentimentale Wert ist UNSCHÄTZBAR!\"" }
entries[80315] = { ["name"] = "Gestohlene Versorgungsgüter", ["text"] = "Questgegenstand\n\"Dieses Bündel enthält größtenteils unbeschadete Güter unterschiedlicher Herkunft.\"" }
entries[80316] = { ["name"] = "Shed-Ling-Glücksfuß", ["text"] = "Questgegenstand\nEinzigartig\n\"Dieser Shed-Ling-Fuß hat schon bessere Tage gesehen. Das Fell ist abgetragen und voller Flecken.\"" }
entries[80317] = { ["name"] = "Glückbringendes Yakhufeisen", ["text"] = "Questgegenstand\nEinzigartig\n\"Dieses rostige alte Yakhufeisen fühlt sich nicht besonders glücksbringend an...\"" }
entries[80318] = { ["name"] = "Glückskleeblatt der Vier Winde", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Blätter an diesem Kleeblatt sind mysteriöserweise makellos.\"" }
entries[80319] = { ["name"] = "\"Goldene\" Glücksmünze", ["text"] = "Questgegenstand\nEinzigartig\n\"Diese Münze hat Ji-Lu auf vielen Reisen begleitet, ist aber so angelaufen, dass sie kaum zu erkennen ist.\"" }
entries[80337] = { ["name"] = "Ken-Kens Maske", ["text"] = "Questgegenstand\nBenutzen: Setzt einem unter Furcht leidenden Mantis Ken-Kens Maske auf." }
entries[80403] = { ["name"] = "Fischspeer der Angler", ["text"] = "Questgegenstand\nBenutzen: Wirft Euren Speer auf ein Ziel in der Nähe. Hoffentlich trefft Ihr einen Fisch!\nVerkaufspreis:" }
entries[80428] = { ["name"] = "Der Leichnam von Dak Dak", ["text"] = "Questgegenstand\n\"Der stinkende Leichnam von Dak Dak, dem hohen Legendenhäuptling der Bruchzahn-Ho-zen.\"" }
entries[80429] = { ["name"] = "Der Leichnam von Ko Ko", ["text"] = "Questgegenstand\n\"Der widerwärtige Leichnam von Ko Ko, dem hohen Jagdhäuptling der Bruchzahn-Ho-zen.\"" }
entries[80430] = { ["name"] = "Der Leichnam von Tak Tak", ["text"] = "Questgegenstand\n\"Der inspirierende Leichnam von Tak Tak, dem hohen Oberhäuptling der Bruchzahn-Ho-zen.\"" }
entries[80431] = { ["name"] = "Gefaltetes Geistereisen", ["text"] = "Verkaufspreis:" }
entries[80432] = { ["name"] = "Schwerer Geistereisenbarren", ["text"] = "Verkaufspreis:" }
entries[80433] = { ["name"] = "Blutgeist", ["text"] = "Handwerksmaterial\n\"Wenn der Geist erweckt wird, wird er danach streben, sich mit den Instrumenten des Krieges zu verbinden.\"\nVerkaufspreis:" }
entries[80437] = { ["name"] = "Gepanzerter Karpfen", ["text"] = "Questgegenstand\n\"Dicke, schwere Schuppen bedecken den Fisch.\"" }
entries[80484] = { ["name"] = "Explosives Fässchen", ["text"] = "Questgegenstand\n\"Am Eingang der Höhle auf dem Ruinenberg platzieren.\"" }
entries[80511] = { ["name"] = "Jubelitkristall", ["text"] = "Questgegenstand\n\"Aus den funkelnden Kristallstrukturen ertönt ein leises Summen.\"" }
entries[80513] = { ["name"] = "Altmodisches Insektenvernichtungsmittel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wendet einen Spritzer Insektenvernichtungsmittel auf eine befallene Pflanze innerhalb von 5 Metern vor dem Zaubernden an.\n\nKann nur auf dem Gehöft Sonnensang eingesetzt werden." }
entries[80528] = { ["name"] = "Explosives Fass", ["text"] = "Kun-Lai-Gipfel\nQuestgegenstand\nEinzigartig\nBenutzen: Abstellen. Zünden. Drehen. Rennen!" }
entries[80529] = { ["name"] = "Stachel eines stacheligen Kugelfisches", ["text"] = "Questgegenstand\n\"Den kann man gar nicht richtig festhalten.\"" }
entries[80535] = { ["name"] = "Schlüssel für Yetifesseln", ["text"] = "Questgegenstand\n\"Dieses ungestalte Metallstück sollte genügen, um die Fesseln des alten Müffels zu öffnen.\"" }
entries[80546] = { ["name"] = "Anstichwerkzeug", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (3)\n\"Werkzeug eines Braumeisters, um ganz besonders hartnäckige Fässer anzustechen.\"" }
entries[80581] = { ["name"] = "Ausgebrannte Glyphe", ["text"] = "Klassen: Paladin\n\"Es sieht zwar aus, als wäre diese Glyphe entsetzlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:" }
entries[80584] = { ["name"] = "Ausgebrannte Glyphe", ["text"] = "Klassen: Paladin\n\"Es sieht zwar aus, als wäre diese Glyphe entsetzlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:" }
entries[80585] = { ["name"] = "Ausgebrannte Glyphe", ["text"] = "Klassen: Paladin\n\"Es sieht zwar aus, als wäre diese Glyphe entsetzlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:" }
entries[80586] = { ["name"] = "Ausgebrannte Glyphe", ["text"] = "Klassen: Paladin\n\"Es sieht zwar aus, als wäre diese Glyphe entsetzlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:" }
entries[80587] = { ["name"] = "Glyphe 'Falkenschmaus'", ["text"] = "Klassen: Krieger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nKritische Treffer mit Eurer Fähigkeit 'Hinrichten' rufen einen Schwarm Aasvögel herbei.\nVerkaufspreis:" }
entries[80588] = { ["name"] = "Glyphe 'Kochende Wut'", ["text"] = "Klassen: Krieger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr werdet so wütend, wenn Ihr Euch in einem Wutzustand befindet, dass Ihr Feuer fangt.\nVerkaufspreis:" }
entries[80590] = { ["name"] = "Saftigleckere Karottensamen", ["text"] = "Benutzen: Pflanzt saftigleckere Karottensaat.\n\"Kann im gepflügten Erdreich des Gehöfts Sonnensang gepflanzt werden.\"\nVerkaufspreis:" }
entries[80591] = { ["name"] = "Frühlingszwiebelsamen", ["text"] = "Benutzen: Pflanzt Frühlingszwiebelsaat.\n\"Kann im gepflügten Erdreich des Gehöfts Sonnensang gepflanzt werden.\"\nVerkaufspreis:" }
entries[80592] = { ["name"] = "Mogukürbissamen", ["text"] = "Benutzen: Pflanzt Mogukürbissamen.\n\"Kann im gepflügten Erdreich des Gehöfts Sonnensang gepflanzt werden.\"\nVerkaufspreis:" }
entries[80593] = { ["name"] = "Rotblütenlauchsamen", ["text"] = "Benutzen: Pflanzt Rotblütenlauchsaat.\n\"Kann im gepflügten Erdreich des Gehöfts Sonnensang gepflanzt werden.\"\nVerkaufspreis:" }
entries[80594] = { ["name"] = "Rosa Rübensamen", ["text"] = "Benutzen: Pflanzt rosa Rübensaat.\n\"Kann im gepflügten Erdreich des Gehöfts Sonnensang gepflanzt werden.\"\nVerkaufspreis:" }
entries[80595] = { ["name"] = "Weiße Rübensamen", ["text"] = "Benutzen: Pflanzt weiße Rübensaat.\n\"Kann im gepflügten Erdreich des Gehöfts Sonnensang gepflanzt werden.\"\nVerkaufspreis:" }
entries[80596] = { ["name"] = "Fass voll Schwarzpulver", ["text"] = "Questgegenstand\nEinzigartig (20)\n\"Ganz, ganz vorsichtig!\"" }
entries[80597] = { ["name"] = "Faszinierendes Mogurelikt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Noch elf davon und man kann sie zu barer Münze machen.\"" }
entries[80598] = { ["name"] = "Zhens Banner", ["text"] = "Questgegenstand\nEinzigartig\n\"Ihr habt die Ehre des Shado-Meisters wiederhergestellt.\"" }
